};

const THEME_PREVIEW_DATA: &[u8] = include_bytes!("../../../assets/theme_preview.rs");

fn run_cache_subcommand(matches: &clap::ArgMatches) -> Result<()> {
    if matches.get_flag("build") {
        #[cfg(feature = "build-assets")]
        {
            let source_dir = match matches.get_one::<String>("source") {
                Some(source) => Path::new(source.as_str()),
                None => PROJECT_DIRS.config_dir(),
            };
            let target_dir = match matches.get_one::<String>("target") {
                Some(target) => Path::new(target.as_str()),
                None => PROJECT_DIRS.cache_dir(),
            };
            let include_integrated_assets = !matches.get_flag("blank");
            let include_acknowledgements = matches.get_flag("acknowledgements");
            let current_version = clap::crate_version!();
            match bat::assets::build(
                source_dir,
                include_integrated_assets,
                include_acknowledgements,
                target_dir,
                current_version,
            ) {
                Ok(()) => {}
                Err(Error::Io(io_error)) => match io_error.kind() {
                    io::ErrorKind::NotFound => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::PermissionDenied => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::AlreadyExists => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::InvalidInput => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::InvalidData => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::Interrupted => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::UnexpectedEof => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::BrokenPipe => {
                        return Err(Error::Io(io_error));
                    }
                    io::ErrorKind::TimedOut => {
                        return Err(Error::Io(io_error));
                    }
                    _ => {
                        return Err(Error::Io(io_error));
                    }
                },
                Err(other) => {
                    return Err(other);
                }
            }
        }
        #[cfg(not(feature = "build-assets"))]
        println!("bat has been built without the 'build-assets' feature. The 'cache --build' option is not available.");
    } else if matches.get_flag("clear") {
        let cache_dir = PROJECT_DIRS.cache_dir();
        let _cached_assets = assets_from_cache_or_binary(true);
        match env::var_os("BAT_CACHE_PATH") {
            Some(env_cache_path) => {
